#include "opensim/services/sqlite_grid_user_plugin.hpp"
#include "opensim/network/osd_json.hpp"
#include <sqlite3.h>
#include <filesystem>
#include <iostream>
using namespace opensim;using namespace services;
std::string hex(std::string_view s){std::string out;for(unsigned char c:s){out+="0123456789abcdef"[c>>4];out+="0123456789abcdef"[c&15];}return out;}
std::string unhex(std::string_view s){std::string out;for(size_t i=0;i<s.size();i+=2)out+=char(std::stoi(std::string(s.substr(i,2)),nullptr,16));return out;}
std::string scalar(sqlite3* db,const char* sql){sqlite3_stmt* q=nullptr;if(sqlite3_prepare_v2(db,sql,-1,&q,nullptr)!=SQLITE_OK){if(q)sqlite3_finalize(q);return "X";}std::string out;if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_type(q,0)!=SQLITE_NULL){auto value=sqlite3_column_text(q,0);out.assign(reinterpret_cast<const char*>(value),sqlite3_column_bytes(q,0));}sqlite3_finalize(q);return out;}
std::string snapshot(sqlite3* db){return hex(scalar(db,"SELECT coalesce(group_concat(name||':'||quote(version),'|'),'') FROM (SELECT name,version FROM migrations ORDER BY name,version)"))+":"+hex(scalar(db,"SELECT coalesce(group_concat(UserID||':'||Online||':'||Login,'|'),'') FROM (SELECT * FROM GridUser ORDER BY UserID)"));}
std::optional<std::string> text(const network::Value& v){if(v.kind==network::Value::Kind::Undefined)return {};auto s=network::osd_string(v);return s=="."?"":s;}
std::optional<SqliteTableStrings> strings(const network::Value& v){if(v.kind!=network::Value::Kind::Array)return {};SqliteTableStrings result;for(auto& x:v.array)result.push_back(text(x));return result;}
std::shared_ptr<GridUserData::Fields> fields(const network::Value& v){if(v.kind!=network::Value::Kind::Array)return {};auto result=std::make_shared<GridUserData::Fields>();for(auto& pair:v.array)(*result)[text(pair.array.at(0)).value()]=text(pair.array.at(1));return result;}
std::string rows(const std::vector<std::shared_ptr<GridUserData>>& values){std::string result=std::to_string(values.size())+"|";for(auto& r:values){result+=hex(r->user_id.value())+":";for(auto& [key,value]:*r->data)result+=hex(key)+"="+hex(value.value_or(""))+",";result+=";";}return result;}
int main(int argc,char**argv){if(argc!=2)return 2;std::string line;int index=0;while(std::getline(std::cin,line)){auto input=network::parse_osd_json(unhex(line));auto path=(std::filesystem::absolute(argv[1])/std::to_string(index++)).string()+".db",other=path+".other";sqlite3 *db=nullptr,*db2=nullptr;if(sqlite3_open(path.c_str(),&db)!=SQLITE_OK||sqlite3_open(other.c_str(),&db2)!=SQLITE_OK)return 3;auto setup=network::osd_string(input.get("setup"));if(sqlite3_exec(db,setup.c_str(),nullptr,nullptr,nullptr)!=SQLITE_OK)return 4;std::string trace;auto event=[&](const std::string& level,std::string message){if(level=="debug"&&message.starts_with("[MIGRATIONS]: Cmd was ")){auto at=message.find(" in SQL: ");if(at!=message.npos)message="[MIGRATIONS]: Cmd was SQLERROR"+message.substr(at);}auto value=level+":"+message;trace+=value+";";if(value==network::osd_string(input.get("fail")))throw std::runtime_error("injected");};MigrationLog log{[&](auto s){event("info",s);},[&](auto s){event("debug",s);},[&](auto s){event("error",s);}};auto state=std::make_shared<SqliteGenericState>();std::map<int,std::unique_ptr<SqliteGridUserPlugin>> slots;std::string output;
 for(auto& op:input.get("ops").array){auto kind=network::osd_string(op.get("op"));std::string result="-";int slot=static_cast<int>(network::osd_integer(op.get("slot")));try{if(kind=="new"){auto connection=network::osd_string(op.get("connection"));for(auto& [from,to]:std::vector<std::pair<std::string,std::string>>{{"$DB",path},{"$OTHER",other}})for(size_t at=connection.find(from);at!=connection.npos;at=connection.find(from,at+to.size()))connection.replace(at,from.size(),to);slots[slot]=std::make_unique<SqliteGridUserPlugin>(connection,network::osd_string(op.get("realm")),log,state);}else if(kind=="get"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");auto rows=slots[slot]->get_all("a");result=std::to_string(rows.size())+"|";for(auto& row:rows){result+=hex(row->user_id.value_or(""))+":";for(auto& [key,value]:*row->data)result+=hex(key)+"="+hex(value.value_or(""))+",";result+=";";}}else if(kind=="dto"){auto a=std::make_shared<GridUserData>();result=std::string(a->user_id?"0":"1")+":"+std::to_string(a->data->size());auto b=std::make_shared<GridUserData>();b->data=a->data;(*b->data)["A"]=std::nullopt;result+=a->data->at("A")?":0":":1";(*a->data)["B"]="two";b->data->erase("A");(*b->data)["C"]="three";result+=a->data==b->data?":1":":0";for(auto& [key,value]:*a->data)result+=":"+key+"="+value.value_or("");}
 else if(kind=="exact"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");auto value=slots[slot]->get_record(text(op.get("user")));result=rows(value?std::vector{value}:std::vector<std::shared_ptr<GridUserData>>{});}
 else if(kind=="all"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");result=rows(slots[slot]->get_all_records(text(op.get("user"))));}
 else if(kind=="where"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");result=rows(slots[slot]->get_where(text(op.get("where"))));}
 else if(kind=="fields"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");auto f=strings(op.get("fields")),k=strings(op.get("keys"));result=rows(slots[slot]->get_fields(f?&*f:nullptr,k?&*k:nullptr));}
 else if(kind=="save"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");auto row=network::osd_boolean(op.get("nullrow"))?std::shared_ptr<GridUserData>{}:std::make_shared<GridUserData>();if(row){row->user_id=text(op.get("user"));row->data=fields(op.get("data"));}result=slots[slot]->store(row)?"1":"0";}
 else if(kind=="store"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");auto row=std::make_shared<GridUserData>();row->user_id="a";row->data=std::make_shared<GridUserData::Fields>();(*row->data)["Online"]="True";(*row->data)["Login"]="7";result=slots[slot]->store(row)?"1":"0";}else if(kind=="delete"){if(!slots.contains(slot))throw std::runtime_error("Missing slot");result=slots[slot]->delete_field("UserID","a")?"1":"0";}else if(kind=="raw"){auto sql=network::osd_string(op.get("sql"));if(sqlite3_exec(db,sql.c_str(),nullptr,nullptr,nullptr)!=SQLITE_OK)throw std::runtime_error("raw");}}catch(...){result="EX";}output+=hex(result)+":"+(state->initialized.load()?"1":"0")+":"+snapshot(db)+":"+snapshot(db2)+";";}
 slots.clear();state.reset();sqlite3_close(db);sqlite3_close(db2);std::cout<<output<<'|'<<hex(trace)<<'\n';}}
